def get_dataset_version_history(
    repository_id: int,
    dataset_id: int,
    db: Session = Depends(get_db),
):
    result = get_dataset_versions(
        db=db,
        dataset_id=dataset_id,
    )

    if result is None:
        raise HTTPException(
            status_code=404,
            detail="Dataset not found",
        )

    dataset, versions = result

    # Make sure the dataset actually belongs
    # to the repository in the URL.
    if dataset.repository_id != repository_id:
        raise HTTPException(
            status_code=404,
            detail="Dataset not found in this repository",
        )

    return {
        "dataset_id": dataset.id,
        "dataset_name": dataset.name,
        "versions": versions,
    }

def get_repository_endpoint(
    repository_id: int,
    db: Session = Depends(get_db),
):
    repository = get_repository(db, repository_id)

    if repository is None:
        raise HTTPException(
            status_code=404,
            detail="Repository not found",
        )

    return repository

def create_repository_endpoint(
    repository_data: RepositoryCreate,
    db: Session = Depends(get_db),
):
    return create_repository(db, repository_data)

def checkout_dataset(
    repository_id: int,
    dataset_id: int,
    version_number: int,
    db: Session = Depends(get_db),
):
    result = checkout_dataset_version(
        db=db,
        dataset_id=dataset_id,
        version_number=version_number,
    )

    if result is None:
        raise HTTPException(
            status_code=404,
            detail="Dataset version not found",
        )

    dataset, version = result

    if dataset.repository_id != repository_id:
        raise HTTPException(
            status_code=404,
            detail="Dataset not found in this repository",
        )

    return {
        "message": f"Dataset checked out to version {version.version_number}.",
        "dataset_id": dataset.id,
        "dataset_name": dataset.name,
        "current_version": version.version_number,
        "current_version_id": version.id,
        "object_hash": version.object_hash,
    }

